    "id": "c013",
    "name": "6. Retention of Rights",
    "text": "renmin of Rights, Any forfeiture of the Payment shalt be without prejudice to any legal right or remedy that the Company may have against you or any other person."
  },
  {
    "id": "c014",
    "name": "7. Interpretation of Agreement",
    "text": "7. Interpretation of Agreement. Any interpretation, construction or application of this Agreement shall be determined by the Company in its sole and absolute discretion and will be final, binding and conclusive for all purposes."
  },
  {
    "id": "c015",
    "name": "8. Successors",
    "text": "8. Successors, The Agreement shall inure to the benefit of and be binding upon each successor and assign of the Company."
